import{_ as o,o as l,c,a3 as d}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/technology-career-guide/13-面试流程篇：不同企业的面试流程到底是怎么样的.md","filePath":"books/technology-career-guide/13-面试流程篇：不同企业的面试流程到底是怎么样的.md","lastUpdated":1782455267000}'),i={name:"books/technology-career-guide/13-面试流程篇：不同企业的面试流程到底是怎么样的.md"};function r(t,e,p,s,n,a){return l(),c("div",null,[...e[0]||(e[0]=[d('<p>一个完整的面试，有一趟全走完的，有分初试和复试的，还有分三四轮面试的，甚至有些还有机试笔试的……总之，不同公司在面试这件事上，具体流程也会存在差异。但其实有着一个潜规则，就是当企业规模越大，面试的轮数就会越多。而这多轮面试的流程是咋样的？每轮面试主要考核哪些内容？这将是本篇的核心内容。</p><p>不过在真正讲面试流程之前，首先还得先搞明白一些求职中的术语，例如<code>HC、JD、OC、Base、SP......</code>，这些名词在面经分享、面试交流贴中十分常见，如若有些小伙伴之前没接触过，看着多少有点云里雾里的感觉。为此，本篇会先讲明这些求职中的术语，接着再分析不同企业的面试流程。</p><h2 id="一、求职时经常遇到的术语名词" tabindex="-1">一、求职时经常遇到的术语名词 <a class="header-anchor" href="#一、求职时经常遇到的术语名词" aria-label="Permalink to &quot;一、求职时经常遇到的术语名词&quot;">​</a></h2><p>经常不上网冲浪的小伙伴，突然听到、看到<code>yyds、emo、xswl...</code>词汇时，一时绝对有点反应不过来。</p><p>而找工作也一样，当大家第一次碰到某些求职术语时，如果之前没接触过，或者是刚入行的小白，也会出现和上面相同的情况。举个例子：</p><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/9375fa07b0b54988821671cbb271e582~tplv-k3u1fbpfcp-watermark.image?" alt="术语对话" loading="lazy"></p><p>当出现这个情况时，相对就有点尴尬了……哈哈~，为了避免这些尴尬的现象发生在我们身上，咱们就得去了解一些求职中会经常出现的名词，接着来挨个说说吧！</p><ul><li><strong>名词</strong>：用语示例。</li><li>名词解释。</li></ul><p>下面介绍每个术语时，会以上述风格进行讲解，先给出名词、再给出例句，最后对其进行解释。</p><ul><li><strong><code>HC</code></strong>：<code>HC</code>充足，欢迎来撩~</li><li><code>HC（Head Count）</code>，俗称人头数，在求职中指招聘名额指数。</li></ul><hr><ul><li><strong><code>Base</code></strong>：招人啦！<code>Base</code>上海/深圳/北京，有意者可私我内推。</li><li><code>Base</code>在内推贴中比较常见，指工作地的意思，还有种意思是指薪资，例如你<code>Base</code>太低。</li></ul><hr><ul><li><strong><code>HR</code></strong>：今天我去面试的那家公司，<code>HR</code>人很好啊。</li><li><code>HR（Human Resource）</code>，人力资源，也习惯称之为人事。</li></ul><hr><ul><li><strong><code>HRM</code></strong>：前面接待我的那个人，似乎是这个公司的<code>HRM</code>。</li><li><code>HRM（Human Resource Manager）</code>，人事经理的意思。</li></ul><hr><ul><li><strong><code>HRD</code></strong>：最后那轮人事面，我记得是<code>HRD</code>跟我聊的。</li><li><code>HRD（Human Resource Director）</code>，人力资源总监的意思。</li></ul><hr><ul><li><strong><code>HRBP</code></strong>：发布这个招聘需求的人，好像是<code>HRBP</code>。</li><li><code>HRBP（Human Resource Business Partner）</code>，指人力资源业务合作伙伴的意思。</li></ul><hr><ul><li><strong><code>PM</code></strong>：今天过去面试的那家公司，是想招一个<code>PM</code>。</li><li><code>PM（Project Manager）</code>，指项目经理、项目负责人的意思。</li></ul><hr><ul><li><strong><code>PD</code></strong>：听说这家公司入职后，天天要和<code>PD</code>吵架。</li><li><code>PD（Product Designer）</code>，一般指产品、产品负责人岗位。</li></ul><hr><ul><li><strong><code>RD</code></strong>：我们公司后端<code>RD</code>只招<code>Java</code>。</li><li><code>RD（Research and Development）</code>，也就是研发工程师的意思。</li></ul><hr><ul><li><strong><code>CTO</code></strong>：我面试被他们公司的<code>CTO</code>吊打了！</li><li><code>CTO（Chief Technology Officer）</code>，这个大家最熟悉，首席技术官、最高技术负责人的意思。</li></ul><hr><ul><li><strong><code>BG/BU</code></strong>：我们这个<code>BG</code>下有三条<code>BU</code>。</li><li><code>BG（Business Group）</code>即事业群的意思，<code>BU（Business Unit）</code>代表业务线的意思。</li></ul><hr><ul><li><strong><code>JD</code></strong>：<code>JD</code>如下，有意者联系！</li><li><code>JD（Job Description）</code>，工作职责描述，一般泛指招聘需求。</li></ul><hr><ul><li><strong><code>Offer</code></strong>：我手里现在有三个<code>Offer</code>。</li><li>这个最常见，<code>Offer</code>代表录用意向书，简单来说就是入职邀约。</li></ul><hr><ul><li><strong><code>OC</code></strong>：我终于<code>OC</code>啦！</li><li><code>OC（Offer Call）</code>，企业决定录用你时，会打电话发<code>Offer</code>，<code>OC</code>指接到入职邀约电话。</li></ul><hr><ul><li><strong><code>OM</code></strong>：面试通过之后，你有没有收到<code>OM</code>？</li><li><code>OM（Offer Mail）</code>，往你的邮箱发<code>Offer</code>，也就是录用邮件的意思。</li></ul><hr><ul><li><strong><code>OD</code></strong>：我现在手里的两个<code>Offer</code>，其中一个是华为<code>OD</code>。</li><li><code>OD（Outsourcing Dispatcher）</code>，通常指外包的意思。</li></ul><hr><ul><li><strong><code>A</code></strong>：你手里这个字节的<code>Offer</code>不错，后面的面阿里可以用来<code>A</code>一下。</li><li><code>A（Argue）</code>，面试时，有更好<code>Offer</code>的情况下，可以用来跟其他公司谈薪。</li></ul><hr><ul><li><strong><code>OT</code></strong>：我网易的<code>OT</code>没通过。</li><li><code>OT（Online Test）</code>，一般指简历筛选后，招聘方发来的在线笔试题。</li></ul><hr><ul><li><strong><code>GA</code></strong>：这家公司的<code>GA</code>面好严格！</li><li><code>GA（Group Assessment）</code>：一般指多位候选人群面，在<code>IT</code>社招面试中较少见。</li></ul><p>至此，求职中经常会遇到的一些术语，就在上面做了简单解释，但诸位稍微看一眼有个印象就行，不需要死记这些玩意儿，毕竟全部记住且不混淆的还是有点难度的。</p><p>接着再来看看<code>Offer</code>薪水的几个名词，以字节的为例（数据图片来自于网络，不确保真实性）：</p><p align="center"><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/5934c73eb7644ab396a53d3c218e6247~tplv-k3u1fbpfcp-watermark.image?" alt="字节薪酬"></p><ul><li><strong>烂白菜</strong>：我拿到了字节的<code>Offer</code>，但却是烂白菜。</li><li>烂白菜则对应着上表中的最低价，也就是最低等的<code>Offer</code>。</li></ul><hr><ul><li><strong>白菜价</strong>：字节校招的白菜价，是<code>(26~29)K * 15</code>。</li><li>白菜价对应着前面的普通<code>Offer</code>，正常人都是拿这个价格。</li></ul><hr><ul><li><strong>SP</strong>：字节给了我一个<code>SP</code>，要不要去呢？</li><li><code>SP（Special Offer）</code>，比常规薪资更好一些的<code>Offer</code>。</li></ul><hr><ul><li><strong>SSP</strong>：我朋友拿到了字节的<code>SSP</code>，羡慕死了！</li><li><code>SSP（Super Special Offer）</code>：显然，这是比<code>SP</code>更高一个档次的<code>Offer</code>。</li></ul><hr><ul><li><strong>总包</strong>：我朋友在字节，一年总包大概在<code>45W</code>上下。</li><li>包含底薪、年终奖、奖金、补贴、股权/期权、福利等在内的年薪总数（通常指税前）。</li></ul><hr><ul><li><strong>房补</strong>：我手里的几个<code>Offer</code>中，只有一个有房补。</li><li>房补的全称就是住房补贴，一般会直接发放到工资卡。</li></ul><hr><ul><li><strong>签字费</strong>：我手里有两个<code>Offer</code>，阿里的给五万签字费，字节的给八万。</li><li>通常指校招生签劳动合同时给的额外福利（社招不一定有）。</li></ul><hr><ul><li><strong>13、14、15、16……薪</strong>：字节给的<code>Offer</code>是<code>28K * 15</code>薪。</li><li>通常是指工作期满一年后，会多发给员工<code>3</code>个月的工资（是否全额发，要看劳动合同）。</li></ul><p>上面简单补充了一些薪资<code>Offer</code>中会出现的术语，大家看完后至少能对这些有所了解，但这套名词通常只会出现在大企业的<code>Offer</code>中，一家<code>30</code>人的企业，<code>Offer</code>还会分普通、<code>SP、SSP</code>嘛？显然不太现实。</p><p>OK，除此之外，有些<code>Offer</code>还会有“<strong>期权、股权、年底分红</strong>”等承诺，而这类玩意儿就比较复杂了，里面门道也很多，大家可以自行先研究研究（后面的《<code>Offer</code>抉择篇》中会展开聊聊）。</p><h2 id="二、求职面试的类型有哪些" tabindex="-1">二、求职面试的类型有哪些？ <a class="header-anchor" href="#二、求职面试的类型有哪些" aria-label="Permalink to &quot;二、求职面试的类型有哪些？&quot;">​</a></h2><p>在本节最开始曾谈到，不同企业、级别的面试，流程也会存在差异，一个完整的面试，可能会出现下述几类情况：</p><ul><li>线下、线上的笔试；</li><li>线上、线下的机试；</li><li>线下的群面；</li><li>心理、性格、英语测试；</li><li>线下的一轮或多轮技术面；</li><li>线下的人事面；</li><li>线下的领导/老板面。</li></ul><p>上面的顺序，是按面试流程的时间线罗列的。</p><p>笔试、机试通常在校招、初中级的面试中比较常见，主要是为了检验应聘者的代码功底与动手能力，而社招出现这两类面试的概率较小。但大厂除外，大厂出现机试的概率较大，不过大厂更多会考数据结构与算法，所以打算冲刺大厂的小伙伴，这块需要好好复盘一下。</p><p>群面、测试类型的面试，虽说我也见过这类情况，但总体占比在技术行业内十分少，毕竟对于技术招聘而言，能干活才是第一位，只要你能力够强，就算性格孤僻也会有不少公司欢迎，有个性的知名牛人也不在少数。</p><p>技术面，这对招聘双方来说，都是最为重要的一轮面试，招聘方会从这轮面试中，来确定应聘者是否可以达到用人标准，而这也将直接决定着候选人能否拿到工作机会。但需注意，技术面可能不仅只有一轮，这里根据企业的不同，会分为多轮面试（稍后会展开细说）。</p><p>人事面，这是技术人最讨厌的一类面试，因为这轮面试中，会出现很多刁钻问题，也会出现谈薪这个重要话题。暂时抛开谈薪不说，对于人事面而言，它并不像技术面那么具有专业性，所以碰到的问题大多属于开放式提问，答案没有绝对的标准，更多的是在考验情商与为人处世。</p><p>领导面/老板面，面试中会碰到这类情况的，要么是应聘的公司规模不大，要么就是你应聘的级别很高，但不管是两者中的任何一种，但凡出现了这类面试，说明你离<code>Offer</code>只有一步之遥！因为企业高管、<code>Boss</code>会更珍惜工作时间，如果你没达到对方的用人需求，他们压根不会在面试中露头，而是喊人事打发你回家等通知。</p><p>OK，到这里简单说明了面试流程中可能会出现的各类面试，对于走社招路线的技术人来说，只需要关注后面三类面试即可，这也是接触最多的三类面试，接下来一起聊聊不同规模的企业会出现的面试流程。</p><h2 id="三、不同企业会出现的面试流程" tabindex="-1">三、不同企业会出现的面试流程 <a class="header-anchor" href="#三、不同企业会出现的面试流程" aria-label="Permalink to &quot;三、不同企业会出现的面试流程&quot;">​</a></h2><p>虽说不同企业会有不一样的面试流程，但总归可分为下述三类模型：</p><ul><li>①一趟到底模型；</li><li>②初试/复试模型；</li><li>③多轮面试模型。</li></ul><p>上述三种面试流程的模型，分别对应着不同规模的企业。</p><p>其中所谓的一趟到底模型，也就是指收到面试邀约后，从初次见面到谈薪，一趟撸到底，这种面试流程在中小型、创业公司中比较常见，因为整个公司人不多，组织架构也不复杂，所以省去了很多流程。作为技术人去面试，只要满足要求、能干活，那么<code>Offer</code>基本跑不掉了。</p><p>对于第一种模型不过多探讨，因为这种面试相信大家都接触过，重点聊聊后面两种，这两种模型在中、大型企业中较为常见，毕竟职场的一条潜规则就是：<strong>规模越大的企业，面试流程会越复杂</strong>，背后的原因大家也能略知一二，这里不过多探讨。</p><h3 id="初试-复试模型" tabindex="-1">初试/复试模型 <a class="header-anchor" href="#初试-复试模型" aria-label="Permalink to &quot;初试/复试模型&quot;">​</a></h3><p>来看看第二种面试模型，会分为初试和复试，各自的作用如下：</p><ul><li>初试：从过来的应聘者中，挑选出与用人需求大致匹配的候选人。</li><li>复试：从多位候选人中，挑选出一/多个最合适的人选。</li></ul><p>这个模型依旧很好理解，无非就是想要选个更合适的罢了，初试一般会出现人事、比你资历老的员工。在初试之前会有简历筛选，被邀请过来面试的人，基本都能大致满足用人需求，初试的这个过程，主要是筛选掉简历水分较大的应聘者，留下一批待考察的候选人。</p><p>等空缺岗位的候选人，达到一定数量时，企业方会发起复试通知，通常时间都在第二周的开始，或者本周的末尾。</p><p>这轮复试通常会出现未来的老大、<code>Boss</code>等一些级别较高的人，考察时不仅仅只关注技术能力，毕竟能通过初试的人选，都能大致满足用人需求。这个环节主要会做综合考察与对比，技术能力、业务经验、为人情商、履历背景、期望薪资……这些都有可能决定着是否能拿到<code>Offer</code>。</p><p>复试阶段拼的是谁更突出，如果你在某一方面比其他候选者有优势，那就很有可能拿到<code>Offer</code>。但如果各个候选者之间难分伯仲，这时就拼的是性价比，也就是谁的报价低，谁就更有希望拿到工作机会。</p><h3 id="多轮面试模型" tabindex="-1">多轮面试模型 <a class="header-anchor" href="#多轮面试模型" aria-label="Permalink to &quot;多轮面试模型&quot;">​</a></h3><p>前面两种模型没啥好聊的，因为大家多少都有所经历，重点是聊聊最后这种多轮面试模型。所谓的多轮，一般是指<code>3</code>轮及以上，每轮都有不同类型的面试官过来面试。通常在大企业的招聘中较为常见，会出现的多轮面试，大体可分为下面四种。</p><ul><li>①用人部门面：一般由资历较老的组员，和组长来负责。</li><li>②兄弟部门面：也称为交叉面试、通道面试……通常由其他部门/业务线的老大来面。</li><li>③内部高层面：也叫大领导面，总监、总经理、<code>CTO、Boss</code>等各类高层，通常在这个环节。</li><li>④人力资源面：通俗的叫法是人事面，主要由企业内部的人力资源部门负责。</li></ul><p><strong>第一轮面试</strong>，通常会由用人部门自己负责，这个是未来组员挑战友、未来老大挑小弟的环节。</p><p>不过虽然是第一轮面试，但也是最有话语权的一轮，这轮将决定着你是否能走到后面的环节，因为来面试你的人，都清楚自己的招聘标准。</p><p>第一轮通常会考察应聘者的技术能力、代码功底、业务理解等，会涉及算法、项目、编码、广度、深度等各方面。</p><p><strong>第二轮面试</strong>，一般是交叉面，不会由用人部门来负责，而是由其他部门或业务线的主管来完成。</p><p>多轮面试模型中，基本上都会有一轮交叉面，主要目的是防止作弊，防止用人部门的员工，直接内推他人入职，设立这轮面试，可以卡住一些“走后门”的家伙。而这轮面试则是综合考察，除开一些敏感话题外，其他方面啥都问。</p><blockquote><p>PS：高层面、人事面，不同的企业顺序有所不同，甚至有些企业会直接将高层面和人事面，合并成一个终面。这里为了方便说明，还是按照之前列出的顺序，将两者分开讲解。</p></blockquote><p><strong>第三轮面试假设是高层面</strong>，那么会出现各类大佬，要么身居高位、要么技术级别很高，通常是你未来的顶头上司，不过一般只有高工级别的面试中会有这轮。</p><p>其面试的方向也偏向于综合考察，但技术方面不会占比很多，更多会出现聊见解、抗压、远景等情况。</p><p>这轮可以说最好过，也可以说最不好过，因为你能通过一、二面，正常发挥的情况下，这轮一般会安稳度过，但如若面试中踩了某个雷区（如价值观不同），由于他是你未来的大领导，所以可以直接挂了你。</p><p><strong>第四轮，也是最后一轮，假设是人事面</strong>，那么会把人事面放到最后一轮的企业，通常对人力资源部门的放权较大，有可能具备一票否决权（如阿里），但大部分企业的人事不具备一票否决权，尤其是用人部门、未来领导极力保你的情况下，具备一定否决权的人事想挂你都难。</p><p>人事面不会聊任何技术，主要会聊个人经历、职业规划、期望薪资等，会考察价值观、安稳度等方面。</p><p>至此，上面就聊了一下多轮面试的模型，下面再说说常见的多轮面试会由哪些类型的面试组成。</p><ul><li>三轮：用人部门一轮、交叉面试一轮、人事+领导一轮。</li><li>四轮：最常见的轮数，分别对应上面提到的四类面试。</li><li>五轮：五轮面试通常会多一轮技术面（也有可能会出现特殊的面试，如测试面、实操面）。</li></ul><p>不管一家企业具体会有多少轮，通常都是由前面提到的四类面试组成。</p><p>正常情况下，最多只会出现五轮面试，但有没有六轮面试的情况呢？很少发生，顶级大厂的面试一般最多也就五轮，除非目前只有一个<code>HC</code>，但出现了两个满意人选，此时或许会加赛一轮，从而造成第六轮面试出现。</p><h3 id="大厂面试流程" tabindex="-1">大厂面试流程 <a class="header-anchor" href="#大厂面试流程" aria-label="Permalink to &quot;大厂面试流程&quot;">​</a></h3><p>最后来说说大厂面试的流程，不多废话直接上张图：</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/86bbf033f4664b4e9c43a3f6dcf92baa~tplv-k3u1fbpfcp-watermark.image?" alt="大厂面试流程" loading="lazy"></p><p>大厂的面试流程会比较长，这是众所周知的一点，上图给出了大厂面试的标准流程（不同企业依旧会有细微差异），图中用虚线标注的阶段可能不会出现，从开始到拿<code>Offer</code>，整个流程为：</p><blockquote><p>投递简历、系统筛选、<code>HR</code>筛选、技术评估、通知面试、线上笔试、多轮面试、录用审核、发放<code>Offer</code>。</p></blockquote><p>这个流程没啥特别值得讲解的，毕竟图中画得很清晰，所以重点只讲明几个注意点。</p><p><strong>第一个注意点，大厂有简历冷却期</strong>。当你投递的简历筛选未通过，又或者在某轮面试中被挂了，这时简历会被标记后放入冷却池，意味着你在冷却期间内，再次投递简历会被系统自动忽略。但有些大厂会有细微不同，比如字节，当你在一条业务线/部门挂了之后，可以继续向其他部门/业务线投递简历。</p><p><strong>第二个注意点，有内推最好别走网申通道</strong>。网申的含义是指通过网络渠道投简历，对于大厂而言，每天都会收到特别多的简历，因此走网申方式，投递简历后的曝光度不高。</p><p>同时最重要的是不能自己锁定心仪的部门，网申渠道通过筛选的简历，都会进入简历池中，需要用人部门去捞，也就意味着你的简历，只能随机由用人部门锁定，而走内推则可以省去这两个麻烦。</p><p><strong>第三个注意点，大厂会有录用审核</strong>。录用审核里面也会包含背调，这个是最关键的一点，如果你简历存在造假的信息，就算你所有面试全部通过，但由于背调不通过的话，最终也会导致拿不到<code>Offer</code>，甚至有可能会被对方列入黑名单。为此，想要尝试冲刺大厂的小伙伴，简历可以包装美化，但千万不能捏造事实。</p><p>至于其他方面就没啥可多说的了，大厂和正常的面试流程类似，只不过稍微繁琐一点罢了，在面的时候注意上述三点即可！</p><h2 id="四、总结" tabindex="-1">四、总结 <a class="header-anchor" href="#四、总结" aria-label="Permalink to &quot;四、总结&quot;">​</a></h2><p>看到这里，本章的内容也走入了尾声。本节首先讲清楚了求职中的常见名词，接着阐述了面试可能出现的各种类型，最后也说到了不同企业的面试流程，提出了三种面试模型，也大致概述了面大厂的完整流程。</p><p>最后，这里也稍微补全一下技术面试中，常规的考察流程：</p><ul><li>自我介绍：作为开场缓冲，面试官想对你有个初步认知。</li><li>基础考察：检验你的基本功是否扎实，考察编码能力。</li><li>项目介绍：推断项目经历的真实性，考察你的业务动手能力。</li><li>技术对线：围绕着技术广度、深度展开，多方面综合考察你的技术能力。</li><li>思维考察：提出一些问题，从而得知你对问题的解决思路、解决方案。</li><li>交流环节：一轮面试的尾声，这个阶段中你可以向面试官提问。</li></ul><p>上述流程则是一轮技术面正规的考察流程，这个流程在之前并没有提及，前面更多的在讲述面试会出现的不同类型，以及探讨不同类型的面试主要会考察的方向。</p><p>而刚刚提到的这个流程，大家也可以稍微记一下，毕竟对于我们来说，最重要的就是技术面，当诸位熟悉技术面试的流程后，才能便于后续面试中掌控节奏。</p>',124)])])}const g=o(i,[["render",r]]);export{f as __pageData,g as default};
